def tables(part, N):
    tl = json.load(open(f"{H}/tl_p{part}.json")); SC = {s["name"]: s for s in tl["scenes"]}; out = []; seg = 0; rows = {}; cur = None; order = []
    for it in SEQS[part]:
        if it[0] == "scene": cur = it[1]; order.append(cur); rows[cur] = []
        elif it[0] == "say": rows[cur].append(f"**{NAME[it[2]]}:** \"{it[3]}\"")
        elif it[0] == "unison": rows[cur].append(f"**{'All three (quietly)' if it[3].get('quiet') else 'All three'}:** \"{it[2]}\"")
        elif it[0] == "chant": rows[cur].append(f"**The chant, call and response:** buddies: \"{' '.join(CHANT[0])}\" (YOUR TURN, one bar) buddies: \"{CHANT[1]}\" (YOUR TURN, one bar) all together: \"{' '.join(CHANT[0])} {CHANT[1]}\"")
        elif it[0] == "wait" and it[1] == .8 and rows[cur] and "Say it with" in rows[cur][-1]: rows[cur].append("(0.8 s)")
        elif it[0] == "mark" and it[1].startswith("ring0"): rows[cur].append("(ring timer)")
    i = 0
    while i < len(order):
        sc = order[i]; head, on, snd, why = N[sc]; j = i + 1
        while j < len(order) and N[order[j]][0] == "": j += 1
        seg += 1; out.append(f"### Segment {seg} · {head} ({mmss(SC[sc]['t0'])}-{mmss(SC[order[j - 1]]['t1'])})\n\n| Time | On screen | Who speaks, exact words | Sound | Why |\n|---|---|---|---|---|")
        for k in range(i, j):
            s2 = order[k]; _, on, snd, why = N[s2]; words = " ".join(rows[s2]) or "(no voice)"
            # the key-word read-along is one long row
            out.append(f"| {mmss(SC[s2]['t0'])} | {on} | {words} | {snd} | {why} |")
        out.append(""); i = j
    return "\n".join(out), tl
t1, tl1 = tables(1, N1); t2, tl2 = tables(2, N2)
words = lambda p: sum(len(i[3].split()) for i in SEQS[p] if i[0] == "say")
body = open(f"{H}/script_frame.md").read()
body = body.replace("{{TABLES1}}", t1).replace("{{TABLES2}}", t2).replace("{{LEN1}}", mmss(tl1["END"])).replace("{{LEN2}}", mmss(tl2["END"])).replace("{{W1}}", str(words(1))).replace("{{W2}}", str(words(2)))
T = lambda tl, n, d=0: mmss(tl["marks"][n] + d) if n in tl["marks"] else mmss(next(s for s in tl["scenes"] if s["name"] == n)["t0"] + d)
for k, v in {"LIZ1": T(tl1, "list", 2), "LIZ2": T(tl2, "fern", 1), "SH1": f"{tl1['marks']['pullout'] - tl1['marks']['dive']:.0f}", "SH2": f"{tl2['marks']['pullout'] - tl2['marks']['dive']:.0f}"}.items(): body = body.replace("{{" + k + "}}", v)
open(f"{H}/../p3_ep04_script.md", "w").write(body); print("written", len(body), "chars;", "left:", re.findall(r"\{\{\w+\}\}", body))
